<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';
require_login();
if (!has_permission('radiology.requests.view') && !has_permission('radiology.results.manage')) { http_response_code(403); exit('Radiology access is not assigned to your account.'); }
if ($_SERVER['REQUEST_METHOD']==='POST') {
    verify_csrf(); $action=(string)($_POST['action']??'');
    if($action==='request'){
        require_permission('radiology.requests.create');$patient=filter_var($_POST['patient_id']??'',FILTER_VALIDATE_INT);$scan=trim((string)($_POST['scan_name']??''));$notes=trim((string)($_POST['clinical_notes']??''));
        if(!$patient||$scan===''||strlen($scan)>160||strlen($notes)>5000){set_flash('danger','Choose a patient, scan type, and optional notes up to 5,000 characters.');redirect('/hospital%20management/radiology/index.php');}
        if(current_user()['role_key']==='doctor'){$check=$pdo->prepare('SELECT id FROM visits WHERE patient_id=:patient AND doctor_id=(SELECT id FROM doctors WHERE user_id=:user) LIMIT 1');$check->execute(['patient'=>$patient,'user'=>current_user()['id']]);if(!$check->fetch()){set_flash('danger','You can only request imaging for a patient you have consulted.');redirect('/hospital%20management/radiology/index.php');}}
        $q=$pdo->prepare('INSERT INTO radiology_requests(patient_id,requested_by,scan_name,clinical_notes) VALUES(:patient,:user,:scan,:notes)');$q->execute(['patient'=>$patient,'user'=>current_user()['id'],'scan'=>$scan,'notes'=>$notes?:null]);$id=(string)$pdo->lastInsertId();record_audit('create','radiology_request',$id,'Imaging request created');set_flash('success','Imaging request sent to Radiology.');
    }elseif($action==='report'){
        require_permission('radiology.results.manage');$id=filter_var($_POST['request_id']??'',FILTER_VALIDATE_INT);$report=trim((string)($_POST['report']??''));
        if(!$id||$report===''||strlen($report)>20000){set_flash('danger','Enter a radiology report up to 20,000 characters.');redirect('/hospital%20management/radiology/index.php');}
        $q=$pdo->prepare("UPDATE radiology_requests SET report=:report,status='completed',performed_by=:user,completed_at=NOW() WHERE id=:id AND status IN ('requested','in_progress')");$q->execute(['report'=>$report,'user'=>current_user()['id'],'id'=>$id]);if($q->rowCount()){record_audit('complete','radiology_request',(string)$id,'Radiology report saved');set_flash('success','Radiology report saved.');}else set_flash('warning','Request not found or already completed.');
    }elseif($action==='start'){
        require_permission('radiology.results.manage');$id=filter_var($_POST['request_id']??'',FILTER_VALIDATE_INT);$q=$pdo->prepare("UPDATE radiology_requests SET status='in_progress',performed_by=:user WHERE id=:id AND status='requested'");$q->execute(['user'=>current_user()['id'],'id'=>$id]);set_flash('success','Request marked in progress.');
    }else{http_response_code(400);exit('Unknown radiology action.');}
    redirect('/hospital%20management/radiology/index.php');
}
$sql='SELECT r.id,r.patient_id,r.scan_name,r.clinical_notes,r.status,r.report,r.requested_at,p.patient_no,p.first_name,p.last_name FROM radiology_requests r JOIN patients p ON p.id=r.patient_id';$params=[];if(current_user()['role_key']==='doctor'){$sql.=' WHERE r.requested_by=:user';$params['user']=current_user()['id'];}$sql.=' ORDER BY r.requested_at DESC LIMIT 200';$query=$pdo->prepare($sql);$query->execute($params);$requests=$query->fetchAll();
$patients=[];if(has_permission('radiology.requests.create')){if(current_user()['role_key']==='doctor'){$q=$pdo->prepare('SELECT DISTINCT p.id,p.patient_no,p.first_name,p.last_name FROM patients p JOIN visits v ON v.patient_id=p.id JOIN doctors d ON d.id=v.doctor_id WHERE d.user_id=:user ORDER BY p.last_name,p.first_name LIMIT 1000');$q->execute(['user'=>current_user()['id']]);$patients=$q->fetchAll();}else{$patients=$pdo->query('SELECT id,patient_no,first_name,last_name FROM patients ORDER BY last_name,first_name LIMIT 1000')->fetchAll();}}
$pageTitle='Radiology';require __DIR__.'/../includes/header.php'; ?>
<div class="page-heading"><div><h2>Radiology and Medical Imaging</h2><p>Manage scan requests and store reports for the care team.</p></div></div>
<?php if(has_permission('radiology.requests.create')): ?><section class="content-card form-card mt-0"><div class="card-heading"><h3>Request imaging</h3></div><form method="post" class="row g-3"><?= csrf_field() ?><input type="hidden" name="action" value="request"><div class="col-md-4"><label class="form-label">Patient</label><select class="form-select" name="patient_id" required><option value="">Select patient</option><?php foreach($patients as $p): ?><option value="<?= (int)$p['id'] ?>"><?= e($p['patient_no'].' · '.$p['last_name'].', '.$p['first_name']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Scan</label><input class="form-control" name="scan_name" maxlength="160" placeholder="e.g. Chest X-ray" required></div><div class="col-md-4"><label class="form-label">Clinical notes</label><input class="form-control" name="clinical_notes" maxlength="5000"></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-primary">Send</button></div></form></section><?php endif; ?>
<section class="content-card"><div class="table-responsive"><table class="table"><thead><tr><th>Requested</th><th>Patient</th><th>Scan</th><th>Clinical notes</th><th>Status / report</th></tr></thead><tbody><?php if(!$requests): ?><tr><td class="empty-state" colspan="5">No imaging requests.</td></tr><?php else: foreach($requests as $r): ?><tr><td><?= e(date('M j, Y g:i a',strtotime($r['requested_at']))) ?></td><td><a href="/hospital%20management/patient/show.php?id=<?= (int)$r['patient_id'] ?>"><?= e($r['last_name'].', '.$r['first_name']) ?></a><br><span class="subtle"><?= e($r['patient_no']) ?></span></td><td><?= e($r['scan_name']) ?></td><td><?= e($r['clinical_notes']?:'—') ?></td><td><?php if($r['report']!==null): ?><details><summary>View report</summary><?= nl2br(e($r['report'])) ?></details><?php elseif(has_permission('radiology.results.manage')): ?><?php if($r['status']==='requested'): ?><form method="post" class="mb-2"><?= csrf_field() ?><input type="hidden" name="action" value="start"><input type="hidden" name="request_id" value="<?= (int)$r['id'] ?>"><button class="btn btn-sm btn-outline-secondary">Start scan</button></form><?php endif; ?><form method="post" class="d-flex gap-2"><?= csrf_field() ?><input type="hidden" name="action" value="report"><input type="hidden" name="request_id" value="<?= (int)$r['id'] ?>"><textarea class="form-control" name="report" rows="2" maxlength="20000" placeholder="Enter report" required></textarea><button class="btn btn-sm btn-primary">Save report</button></form><?php else: ?><?= e(ucfirst(str_replace('_',' ',$r['status']))) ?><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div></section>
<?php require __DIR__.'/../includes/footer.php'; ?>
